import type { Readable } from 'node:stream';

export interface StoredObject {
  readonly size: number;
}

export interface ReadOptions {
  /** Inclusive byte range, as in an HTTP Range header. */
  readonly start?: number;
  readonly end?: number;
}

/**
 * Where media bytes live (docs/ARCHITECTURE.md section 9). The local implementation writes to
 * disk; a hosted S3-compatible implementation can replace it behind the same interface.
 *
 * Keys are generated by the server, never taken from users, and must match `^[a-z0-9][a-z0-9/_.-]*$`
 * with no `..` segment.
 */
export interface Storage {
  /** Writes the stream to `key`, replacing nothing: it fails if the key already exists. */
  put(key: string, source: Readable): Promise<StoredObject>;
  /** Streams an object (or a byte range of it). Rejects if it does not exist. */
  read(key: string, options?: ReadOptions): Promise<Readable>;
  stat(key: string): Promise<StoredObject | null>;
  /** Removes an object. Missing objects are not an error. */
  delete(key: string): Promise<void>;
}

const KEY = /^[a-z0-9][a-z0-9/_.-]*$/;

export function assertValidKey(key: string): void {
  if (
    key.length > 300 ||
    !KEY.test(key) ||
    key.split('/').some((part) => part === '' || part === '.' || part === '..')
  ) {
    throw new Error('Invalid storage key');
  }
}
